def apply_event(view: View, ui: Ui, action: str, arg: Any) -> None:
    """Change a view's Ui for an event from its component (render_component lists the actions).
    'page' is not here: it fetches, so the state's event handler does it.
    """
    match action:
        case "sort" if view.frame is not None:
            # Glide sends the bare column index, despite the
            # (col, row) tuple in Reflex's event spec.
            col = arg if isinstance(arg, int) else arg[0]
            # the columns shown, ie after the SQL query
            columns = view.table(ui)[0].columns
            if 0 <= col < len(columns):
                name = columns[col]
                # a header click cycles that column: ascending -> descending -> unsorted
                if name != ui.sort_col:
                    ui.sort_col, ui.descending = name, False
                elif not ui.descending:
                    ui.descending = True
                else:
                    ui.sort_col, ui.descending = "", False
        case "query":
            ui.query = str(arg)
        case "play":
            ui.playing, ui.list_hidden, ui.autoplay = dict(arg), True, True
        case "stop":
            ui.playing, ui.list_hidden = {}, False
        case "toggle_list":
            ui.list_hidden = not ui.list_hidden
        case "window":
            ui.window = str(arg)
        case "form_toggle":
            ui.form_open = not ui.form_open
            if not ui.form_open:
                drop_proposal(ui)
        case "ai_toggle":
            # the Ask AI box (in the bar) belongs to the form: opening it unfolds the form
            if ui.ai_open:
                drop_proposal(ui)
            else:
                ui.ai_open = ui.form_open = True
        case "ai_discard":
            drop_proposal(ui)
        case "sql_toggle":
            ui.sql_open = not ui.sql_open
        case "sql":
            text = str(arg).strip().rstrip(";").strip()
            ui.sql = "" if " ".join(text.lower().split()) in ("", DEFAULT_SQL) else text
        case "sql_reset":
            ui.sql, ui.sql_resets = "", ui.sql_resets + 1
        case "db_toggle":
            name = str(arg)
            ui.db_open = [t for t in ui.db_open if t != name] if name in ui.db_open else [*ui.db_open, name]
        case "db_draft":
            ui.draft = str(arg)
        case "db_history":
            ui.history_open = not ui.history_open
        case "db_pick":
            ui.draft, ui.db_resets, ui.history_open = str(arg), ui.db_resets + 1, False
        case "db_save_toggle":
            ui.save_open, ui.save_note, ui.save_error = not ui.save_open, "", ""


def drop_proposal(ui: Ui) -> None:
    """Close a form's inline chat; the inputs go back to the ones that made the result."""
    if ui.proposed:
        ui.proposals += 1
    ui.proposed = {}
    ui.ai_open = ui.ai_busy = False
    ui.ai_note = ui.ai_error = ""


@dataclasses.dataclass
class View:
    """A value and how to show it, on the Python side (keeps the object and its DataFrame, so a
    table can be re-sorted and filtered). data() makes the ViewData sent to the browser.
    """

    kind: str
    value: Any
    """The original Python object (what a tab's name is bound to)."""
    summary: str = ""
    """Short text for tabs and chat, eg '120 × 8', '10 VODs', 'PlayerUsage'."""
    note: str = ""
    frame: pl.DataFrame | None = None
    videos: list[dict[str, str]] = dataclasses.field(default_factory=list)
    fields: list[dict[str, str]] = dataclasses.field(default_factory=list)
    sections: list[Section] = dataclasses.field(default_factory=list)
    page: int = 1
    pages: int = 1

    def table(self, ui: Ui) -> tuple[pl.DataFrame, str]:
        """The frame as shown before filter and sort: the Ui's SQL query run on it (as `self`),
        and the query's error ("" if none; on an error the table is shown as it is).
        """
        if self.frame is None or not ui.sql:
            return self.frame, ""
        try:
            return self.frame.sql(ui.sql), ""
        except Exception as error:  # noqa: BLE001  # any bad query is shown in the view
            # polars appends the query plan it got to; its first line says what is wrong
            first = next(iter(str(error).strip().splitlines()), repr(error))
            return self.frame, f"SQL: {first.strip(chr(39) + chr(34))}"

    def data(
        self,
        slot: str = "",
        ui: Ui | None = None,
        compact: bool = False,
        inputs: dict[str, Any] | None = None,
        can_restore: bool = False,
    ) -> ViewData:
        """The browser's copy, for the place it is shown (slot) with what the user did there
        (ui). Tables are filtered and sorted here; compact sizes the grid to its content.
        inputs: the tool inputs that made the value, when known (Session.call_at), for its tool
        form; can_restore: they were changed from the agent's own call, which can be put back.
        """
        ui = ui or Ui()
        query, sort_col, descending = ui.query, ui.sort_col, ui.descending
        data = ViewData(
            kind=self.kind,
            slot=slot,
            error=ui.error,
            label=type_text(self.value),
            label_parts=type_parts(self.value),
            note=self.note or self.summary,
            query=query,
            videos=self.videos,
            page=self.page,
            pages=self.pages,
            paging=ui.paging,
            playing=ui.playing,
            list_hidden=ui.list_hidden and bool(ui.playing),
            autoplay=ui.autoplay,
            fields=self.fields,
            sections=self.sections,
        )
        if form := form_for(self.value):
            if isinstance(self.value, ToolRequest):
                inputs, data.label, data.note = self.value.inputs, form.title, "not run yet"
            data.form, data.form_open, data.running = form.fields(inputs or {}), ui.form_open, ui.running
            data.form_key, data.form_changed = f"{slot}#{ui.runs}.{ui.proposals}", can_restore
            data.ai_open, data.ai_busy, data.ai_note, data.ai_error = ui.ai_open, ui.ai_busy, ui.ai_note, ui.ai_error
            if ui.proposed:
                data.form, data.ai_proposed = _proposed_fields(form, inputs or {}, ui.proposed), True
        if isinstance(self.value, PlayerUsage):
            _usage_data(self.value, ui, data)
        if isinstance(self.value, WebPage):
            verdict = {True: "yes", False: "no", None: "unknown"}[self.value.frameable]
            data.web = {
                "url": self.value.url,
                "src": self.value.src,
                "host": self.value.host,
                "frameable": verdict,
                "why": self.value.why,
            }
        if isinstance(self.value, DbConsole):
            _console_data(self.value, ui, data)
        if self.frame is None:
            return data
        df, sql_error = self.table(ui)
        data.error = data.error or sql_error
        data.sql, data.sql_open, data.sql_active = ui.sql or DEFAULT_SQL, ui.sql_open, bool(ui.sql) and not sql_error
        data.sql_columns, data.sql_key = list(self.frame.columns), f"{slot}#{ui.sql_resets}"
        data.columns, data.rows = grid_data(df, query, sort_col, descending)
        data.sort_col, data.sort_desc = sort_col, descending
        shown = len(data.rows)
        if compact:
            data.note = f"{df.height} × {df.width}" + (f" ({shown} shown)" if shown < df.height else "")
            data.height = _grid_height(shown)
            data.width = _grid_width(data.columns)
        else:
            data.note = f"{shown} of {df.height} rows" if shown != df.height else f"{df.height} rows"
            if shown == MAX_GRID_ROWS and df.height > MAX_GRID_ROWS:
                data.note += f" (grid shows the first {MAX_GRID_ROWS})"
        if isinstance(self.value, DbConsole):
            data.note += f" · {self.value.timing}"
        return data


def _proposed_fields(form: ToolForm, inputs: dict[str, Any], proposed: dict[str, str]) -> list[FormField]:
    """A form's fields showing the AI's proposal: each one that differs from the inputs that
    made the result is marked changed, its tooltip starting with the old value.
    """
    before = form.texts(inputs)
    fields = form.fields({**inputs, **proposed})
    for item in fields:
        was = before.get(item.name, "")
        if item.value != was:
            item.changed = True
            item.help = f"Was: {was or '(empty)'}. {item.help}".strip()
    return fields


# -- match 1: Python value -> View ------------------------------------------------


def to_view(value: Any) -> View | None:
    """The View for a value, chosen by its type; None when it has none (shown as its repr).

    Cases are tried top to bottom, so specific types go above general ones (eg MatchVideos
    above BaseModel).
    """
    with contextlib.suppress(Exception):  # a value that can't be shown must not break the cell
        match value:
            case MatchVideos():
                return _videos_view(value)
            case PlayerUsage():
                return _usage_view(value)
            case ToolRequest():
                return View(kind="tool", value=value, summary="not run yet")
            case WebPage():
                return View(kind="browser", value=value, summary=value.host)
            case DbConsole():
                frame = value.df
                summary = f"{frame.height} × {frame.width}" if frame is not None else "not run yet"
                return View(kind="smashdb", value=value, frame=frame, summary=summary)
            case TableResult():
                return _table_view(value, value.to_df())
            case pl.DataFrame() | pl.Series():
                return _table_view(value, as_frame(value))
            case BaseModel():
                return _model_view(value)
            case list() | tuple() if _is_models(value):
                # a list of models is a table, one row per model
                # typed from the model's fields (ds.util.df.to_df): a date is a date
                # column. Models of several classes have no one schema: their JSON form
                if len({type(model) for model in value}) == 1:
                    return _table_view(value, to_df(value))
                rows = [model.model_dump(mode="json") for model in value]
                return _table_view(value, pl.DataFrame(rows, infer_schema_length=None))
            case _ if (frame := as_frame(value)) is not None:  # pandas
                return _table_view(value, frame)
    return None


def as_frame(value: Any) -> pl.DataFrame | None:
    """The value as a polars DataFrame if it is tabular (polars
    DataFrame/Series, pandas DataFrame), else None.
    """
    if isinstance(value, pl.DataFrame):
        return value
    if isinstance(value, pl.Series):
        return value.to_frame()
    if type(value).__module__.startswith("pandas") and type(value).__name__ in {"DataFrame", "Series"}:
        with contextlib.suppress(Exception):  # odd pandas dtypes polars can't take: fall back to repr
            return pl.from_pandas(value)
    return None


def _table_view(value: Any, frame: pl.DataFrame) -> View:
    return View(kind="table", value=value, frame=frame, summary=f"{frame.height} × {frame.width}")


def _videos_view(value: MatchVideos) -> View:
    query = value.query
    versus = " vs ".join(
        " ".join(part for part in side if part)
        for side in [(query.player_1, query.char_1), (query.player_2, query.char_2)]
        if any(side)
    )
    what = " · ".join(part for part in [versus, query.search_term, query.region] if part)
    found = [what, f"{value.total} found", f"page {value.page} of {value.pages}"]
    return View(
        kind="vods",
        value=value,
        summary=f"{len(value.videos)} VOD{'' if len(value.videos) == 1 else 's'}",
        note=" · ".join(part for part in found if part),
        videos=[
            {
                "id": video.video_id,
                "title": video.title,
                "date": str(video.date or ""),
                "players": ", ".join(video.players),
                "url": video.url,
                "thumb": video.thumbnail_url,
                "embed": video.embed_url,
            }
            for video in value.videos
        ],
        page=value.page,
        pages=value.pages,
    )


def _usage_view(value: PlayerUsage) -> View:
    lookup, window = value.lookup, value.window
    span = f"{window.first_date} to {window.last_date}" if window.first_date else "no sets"
    versus = f"vs {', '.join(str(c.label) for c in value.vs_characters)}" if value.vs_characters else ""
    where = f"{value.setting} only" if value.setting != "all" else ""
    events = f" from {window.events} event{'s' if window.events != 1 else ''}" if window.events else ""
    counts = f"newest {window.sets} sets{events}, {window.games} games"
    note = " · ".join(part for part in [lookup.tag, versus, where, span, counts] if part)
    return View(kind="usage", value=value, summary=lookup.tag or "player usage", note=note)


_SETTINGS = {
    "all": ("All", "Online and in-person events"),
    "offline": ("Offline", "In-person events only (fetched again: reaches further back)"),
    "online": ("Online", "Online events only (fetched again)"),
}
_WINDOW_LABELS = {"recent": "All games", "game_1": "Game 1", "last_events": "Events"}
_WINDOW_TIPS = {
    "recent": "Every game in the window",
    "game_1": "The character they open a set with",
    "last_events": "Events (not games) among the last ones listed",
}


def _icon_url(name: str) -> str:
    icon = char_icon_by_name(name)
    return ICON_URL + icon if icon else ""


def _bar_rows(items: list[tuple[str, str, float, int]], unit: str) -> list[BarRow]:
    """Ranked rows from (label, full name, share 0-100, count), largest first as given; past
    MAX_BAR_ROWS the tail folds into one "N others" row.
    """

    def row(label: str, name: str, pct: float, count: int, icon: str = "") -> BarRow:
        return BarRow(
            label=label,
            icon=icon,
            width=f"{max(0.0, min(100.0, pct)):.1f}%",
            value=f"{pct:.0f}%" if pct >= 1 or pct == 0 else "<1%",
            tip=f"{name}: {count} {unit} ({pct:.1f}%)",
        )

    shown = items if len(items) <= MAX_BAR_ROWS else items[: MAX_BAR_ROWS - 1]
    rows = [row(label, name, pct, count, _icon_url(name)) for label, name, pct, count in shown]
    if rest := items[len(shown) :]:
        names = ", ".join(name for _, name, _, _ in rest)
        label = f"{len(rest)} others"
        rows.append(row(label, f"{label} ({names})", sum(i[2] for i in rest), sum(i[3] for i in rest)))
    return rows


def _char_group(stats: CharacterStats) -> BarGroup:
    items = [(usage.character, usage.character, usage.usage_pct, usage.count) for usage in stats.characters]
    rows = _bar_rows(items, stats.unit)
    return BarGroup(title="Characters", note=f"{stats.total} {stats.unit}", rows=rows, icons=True)


def _stage_group(title: str, stats: StageStats) -> BarGroup:
    items = [(stage.stage, stage.stage, stage.usage_pct, stage.games) for stage in stats.stages]
    return BarGroup(title=title, note=f"{stats.games} games", rows=_bar_rows(items, "games"))


def _switch_note(value: PlayerUsage) -> str:
    """One line on changing character within a set ('' with nothing to go on)."""
    switches = value.switches
    if not switches.sets:
        return ""
    parts = [f"Changed character in {switches.sets_with_switch} of {switches.sets} sets"]
    if switches.chances_after_losing:
        parts.append(f"{switches.switched_after_losing} of {switches.chances_after_losing} games after dropping one")
    if switches.chances_after_winning:
        parts.append(f"{switches.switched_after_winning} of {switches.chances_after_winning} after taking one")
    return " · ".join(parts)


def rerun_inputs(view: View, action: str, arg: Any) -> dict[str, Any] | None:
    """The tool inputs for a view event that needs the
    view's tool run again (None: it doesn't).

    'setting' on a usage view: the same player, character and sets, for other events. The
    inputs come from the result itself, so this works on a result the agent made too.
    """
    value = view.value
    if action == "setting" and isinstance(value, PlayerUsage) and arg in _SETTINGS and arg != value.setting:
        return {
            "player": value.lookup.query,
            "vs_characters": ",".join(value.vs_characters),
            "setting": arg,
            "sets": str(value.window.requests * USAGE_PER_PAGE),
        }
    return None


def _usage_data(value: PlayerUsage, ui: Ui, data: ViewData) -> None:
    """Fill a usage view: the characters of the picked
    window, the stage groups, recent events.
    """
    windows = {"recent": value.recent, "game_1": value.game_1, "last_events": value.last_events.characters}
    picked = ui.window if ui.window in windows else "recent"
    data.windows = [
        {"key": key, "label": _WINDOW_LABELS[key], "tip": _WINDOW_TIPS[key], "on": "1" if key == picked else ""}
        for key in windows
    ]
    data.chars = _char_group(windows[picked])
    data.stage_groups = [
        _stage_group("Starters", value.starters),
        _stage_group("Counterpicks", value.counterpicks),
        _stage_group("Taken to", value.taken_to),
    ]
    data.settings = [
        {"key": key, "label": label, "tip": tip, "on": "1" if key == value.setting else ""}
        for key, (label, tip) in _SETTINGS.items()
    ]
    data.switch_note = _switch_note(value)
    recent = value.last_events
    data.events = [
        EventRow(
            date=event.date.isoformat(),
            title=event.tournament,
            tip=f"{event.tournament} · {event.event}",
            where="" if event.online is None else "online" if event.online else "offline",
            url=event.url or "",
            icons=[
                {
                    "name": f"{used.character} ({used.games} game{'' if used.games == 1 else 's'})",
                    "url": _icon_url(used.character),
                }
                for used in event.characters
            ],
        )
        for event in recent.events
    ]
    if recent.first_date and recent.last_date:
        data.events_note = f"{recent.first_date.isoformat()} to {recent.last_date.isoformat()}"


def _console_data(value: DbConsole, ui: Ui, data: ViewData) -> None:
    """A SmashDb console's own part of its ViewData: the schema tree, the editor and the
    history. The schema is read from the db each time (about
    1 ms), so a table a query made shows at once.
    """
    data.label = "SmashDb"
    data.db_tables = value.tables(ui.db_open)
    data.db_schema = {table.name: [column["name"] for column in table.columns] for table in data.db_tables}
    data.db_sql, data.db_key = ui.draft or value.sql, f"{data.slot}#{ui.db_resets}"
    data.db_ran, data.running = value.df is not None, ui.running
    data.db_history, data.db_history_open = list(value.history), ui.history_open
    data.db_save_open, data.db_save_key = ui.save_open and value.df is not None, f"{data.slot}#save{ui.saves}"
    data.db_save_note, data.db_save_error = ui.save_note, ui.save_error
    data.trace = ui.trace.get("trace", [])
    data.trace_hidden = ui.trace.get("trace_hidden", [])
    data.trace_more = ui.trace.get("trace_more", "")
    data.trace_text = ui.trace.get("text", "")


def _text(value: Any) -> str:
    if value is None:
        return ""
    if isinstance(value, str):
        text = value
    elif isinstance(value, dict | list | tuple | set):
        text = json.dumps(value, default=str, ensure_ascii=False)
    else:
        text = str(value)
    return text if len(text) <= MAX_VALUE_CHARS else text[:MAX_VALUE_CHARS] + "…"


def _is_models(value: Any) -> bool:
    return isinstance(value, list | tuple) and len(value) > 0 and all(isinstance(item, BaseModel) for item in value)


def _section(title: str, models: list[BaseModel]) -> Section:
    rows = [model.model_dump(mode="json") for model in models[:MAX_SECTION_ROWS]]
    columns = list(dict.fromkeys(key for row in rows for key in row))
    return Section(title=title, columns=columns, rows=[[_text(row.get(column)) for column in columns] for row in rows])


def _walk(model: BaseModel, prefix: str, fields: list[dict[str, str]], sections: list[Section]) -> None:
    """Flatten a model: scalars become 'a.b' fields, lists of models become sections."""
    names = [*type(model).model_fields, *type(model).model_computed_fields]
    for name in names:
        value = getattr(model, name)
        path = f"{prefix}{name}"
        if isinstance(value, BaseModel):
            _walk(value, f"{path}.", fields, sections)
        elif _is_models(value):
            sections.append(_section(path, list(value)))
            # models inside the list's items (eg stats per
            # window) are shown as JSON in the table
        else:
            fields.append({"name": path, "value": _text(value)})


def _model_view(value: BaseModel) -> View:
    fields: list[dict[str, str]] = []
    sections: list[Section] = []
    _walk(value, "", fields, sections)
    return View(kind="fields", value=value, summary=type(value).__name__, fields=fields, sections=sections)


# -- table shaping ----------------------------------------------------------------


def dtype_label(dtype: pl.DataType) -> str:
    """Polars' short dtype name as in its table repr:
    i64, f64, str, list[str], datetime[μs].
    """
    with contextlib.suppress(Exception):  # private polars helper; fall back to the long name
        return dtype._string_repr()  # noqa: SLF001  # polars has no public short dtype name
    return str(dtype)


def _column_width(title: str, column: pl.Series) -> int:
    """Pixel width (12px mono) that fits the header title
    or the longest of the first 200 values.
    """
    # str() per value, not a polars cast: list and struct columns can't be cast to String
    sample = ["" if value is None else str(value) for value in column.head(200).to_list()]
    longest = max([len(title) + 1, *(len(value) for value in sample)])
    return max(48, min(240, round(7.3 * longest) + 18))


def grid_data(
    df: pl.DataFrame, query: str, sort_col: str, descending: bool
) -> tuple[list[dict[str, Any]], list[list[Any]]]:
    """Filter and sort df, then shape it for the grid:
    (columns, rows), capped at MAX_GRID_ROWS.
    """
    if query:
        with contextlib.suppress(Exception):  # columns that can't be shown as text just don't match
            text = pl.concat_str(pl.all().cast(pl.String, strict=False).fill_null(""), separator=" ")
            df = df.filter(text.str.to_lowercase().str.contains(query.lower(), literal=True))
    if sort_col in df.columns:
        with contextlib.suppress(Exception):  # unsortable dtypes stay in original order
            df = df.sort(sort_col, descending=descending, nulls_last=True)
    df = df.head(MAX_GRID_ROWS)

    columns: list[dict[str, Any]] = []
    numeric: list[bool] = []
    for name, dtype in df.schema.items():
        # The grid's number cells can't show nulls, so
        # only null-free numeric columns stay numbers.
        is_number = (
            dtype.is_numeric() and df[name].null_count() == 0 and not (dtype.is_float() and df[name].is_nan().any())
        )
        numeric.append(is_number)
        arrow = (" ▼" if descending else " ▲") if name == sort_col else ""
        label = dtype_label(dtype)
        columns.append(
            {
                "title": name + arrow,
                "id": name,
                # read by the grid's drawHeader callback (draw_header
                # below): dtype on a second, italic line
                "dtype": label,
                "type": ("float" if dtype.is_float() else "int") if is_number else "str",
                # fixed widths sized to content, with room for the sort arrow
                "width": _column_width(max(f"{name} ▲", label, key=len), df[name]),
            }
        )
    rows = [
        [value if numeric[i] else ("" if value is None else str(value)) for i, value in enumerate(row)]
        for row in df.rows()
    ]
    return columns, rows


def _grid_height(rows: int) -> str:
    """Show up to OUTPUT_VISIBLE_ROWS rows, then scroll inside the grid."""
    return f"{OUTPUT_HEADER_HEIGHT + 2 + OUTPUT_ROW_HEIGHT * max(1, min(rows, OUTPUT_VISIBLE_ROWS))}px"


def _grid_width(columns: list[dict[str, Any]]) -> str:
    """Only as wide as the columns, never wider than the cell."""
    total = OUTPUT_MARKER_WIDTH + sum(int(column.get("width", 0)) for column in columns)
    return f"min(100%, {total}px)"


# -- match 2: ViewData -> component -------------------------------------------------


def render_component(
    view: rx.Var[ViewData],
    on_event: Any,
    *,
    compact: bool = False,
    actions: tuple[rx.Component, ...] = (),
) -> rx.Component:
    """The one component for a view, chosen by its kind, with everything that belongs to it.

    The same component and logic wherever it is placed. Its state is in the view (ViewData);
    what the user does comes back as on_event(view.slot, action, arg) with action one of:
    sort (column index), query (text), play (video), stop, toggle_list, page (-1 / 1).

    Args:
        view: the ViewData var, eg State.view or a cell's view.
        on_event: the host's one event handler, called with (slot, action, arg).
        compact: sizing only: fit the content (a cell output) instead of filling the space (a
        tab). actions: the host's own buttons for the
        component's bar, eg a cell's "open as tab".
    """

    def send(action: str, arg: Any = "") -> Any:
        return on_event(view.slot, action, arg)

    def on_sort(pos: Any) -> Any:
        return send("sort", pos)

    if compact:
        grid = compact_grid(columns=view.columns, rows=view.rows, height=view.height, on_sort=on_sort)
    else:
        grid = full_grid(view, on_sort)
    return rx.el.div(
        rx.match(
            view.kind,
            ("vods", video_widget(view, send, actions)),
            ("usage", usage_widget(view, send, actions)),
            # a tool form added by hand, before its first run: just the form
            (
                "tool",
                rx.fragment(
                    # closer: only the close button (send= would add a second AI button)
                    _bar(view, actions, ai_toggle(view, send), closer=send),
                    form_section(view, send),
                    _error(view),
                    rx.el.div("Fill in the inputs and press Enter to run it.", class_name="empty sans"),
                ),
            ),
            ("fields", rx.fragment(_bar(view, actions, send=send), model_fields(view.fields, view.sections))),
            ("table", table_widget(view, send, grid, actions)),
            ("smashdb", db_console_widget(view, send, grid, actions)),
            ("browser", browser_widget(view, send, actions)),
            rx.fragment(),
        ),
        # a compact table is only as wide as its columns
        style={"width": rx.cond(view.kind == "table", view.width, "auto")} if compact else {},
        # where it is shown: assets/panes.js finds the glance's Browser by it (tab:web)
        custom_attrs={"data-slot": view.slot},
        class_name="widget cell-widget" if compact else "widget",
    )


def close_view_button(send: Any) -> rx.Component:
    """Top right of every view, after its float button: close it, as fits where it is shown
    (State.view_event "close"): a Results tab closes, a glance closes (the layout goes
    back), a chat row folds, a cell's output is hidden. assets/panes.js puts a floating
    view back first.
    """
    return rx.el.button(
        "×",
        title="Close",
        aria_label="Close",
        on_click=send("close"),
        custom_attrs={"data-close-view": ""},
        class_name="float-btn close-view-btn mono",
    )


def float_button() -> rx.Component:
    """Top right of every view: float it over the page, nearly full screen (or put it back).

    Purely in the browser (assets/panes.js toggles .is-floating on the view's .widget), so the
    view stays the same component: its sort, filter and playing video carry on. The
    Shortcut.FULL_SCREEN keys do the same for the view you are in.
    """
    return rx.el.button(
        rx.el.span(ICON_EXPAND, class_name="when-docked"),
        rx.el.span(ICON_COLLAPSE, class_name="when-floating"),
        title=Shortcut.FULL_SCREEN.hint("Float full screen / put back"),
        aria_label="Float full screen",
        class_name="float-btn mono",
    )


def type_label(parts: rx.Var) -> rx.Component:
    """A type as text (typeinfo.type_parts), the model's name in it underlined: hovering it
    shows the class as Python code (assets/typehover.js reads data-type-code).
    """
    return rx.fragment(
        parts["pre"],
        rx.cond(
            parts["model"] != "",
            rx.el.span(
                parts["model"],
                custom_attrs={"data-type-code": parts["code"], "data-type-html": parts["html"]},
                class_name="type-model",
            ),
        ),
        parts["post"],
    )


def typed_text(parts: rx.Var, text: rx.Var) -> rx.Component:
    """A row's "type · the rest" (a variable's chat row): the type as type_label shows it."""
    has_type = (parts["pre"] != "") | (parts["model"] != "")
    return rx.fragment(type_label(parts), rx.cond(has_type & (text != ""), " · ", ""), text)


def _bar(
    view: rx.Var[ViewData],
    actions: tuple[rx.Component, ...],
    *controls: rx.Component,
    hidden: Any = False,
    send: Any = None,
    closer: Any = None,
) -> rx.Component:
    """The component's top bar: what the value is, the kind's own controls, the host's actions.
    With send (the view's event sender), a view that has a tool form gets its Inputs button;
    send (or closer, for the close alone) also gives the bar its × (close_view_button).
    """
    return rx.el.div(
        rx.el.span(
            rx.cond(
                (view.label_parts["model"] != "") & (view.label_parts["text"] == view.label),
                type_label(view.label_parts),
                view.label,
            ),
            class_name="out-kind",
        ),
        rx.cond(view.note != view.label, rx.el.span(view.note, class_name="dim")),
        # the free width: the form's inline AI box while it is open, so the inputs below never
        # move (spec/services/ui/README.md, "Toggles don't move the content")
        rx.cond(view.ai_open & (view.form.length() > 0), strip_ask_box(view), rx.el.span(class_name="spacer")),
        *controls,
        # every view with a tool form (widgets.py) gets
        # its Inputs button and the AI that fills it
        rx.cond(view.form.length() > 0, rx.fragment(ai_toggle(view, send), form_toggle(view, send)))
        if send
        else rx.fragment(),
        *actions,
        float_button(),
        close_view_button(closer or send) if (closer or send) else rx.fragment(),
        class_name=rx.cond(hidden, "viewer-bar sans is-hidden", "viewer-bar sans"),
    )


def _error(view: rx.Var[ViewData]) -> rx.Component:
    return rx.cond(view.error != "", rx.el.div(view.error, class_name="view-error sans"))


def _table_bar(
    view: rx.Var[ViewData], send: Any, actions: tuple[rx.Component, ...], *controls: rx.Component
) -> rx.Component:
    """A table's bar: the SQL toggle and the row filter
    (after the host widget's own controls).
    """
    return _bar(
        view,
        actions,
        *controls,
        rx.el.button(
            rx.cond(view.sql_open, "SQL ▾", "SQL ▸"),
            title=rx.cond(view.sql_active, "A SQL query is applied: show or hide it", "Query this table with SQL"),
            on_click=send("sql_toggle"),
            class_name=rx.cond(view.sql_active, "act sql-toggle is-active", "act sql-toggle"),
        ),
        rx.el.input(
            placeholder="Filter rows…",
            value=view.query,
            on_change=lambda value: send("query", value),
            class_name="viewer-filter",
        ),
        send=send,
    )


def _table_body(view: rx.Var[ViewData], send: Any, grid: rx.Component) -> rx.Component:
    """Under a table's bar: the SQL box (folded by default), an error, then the grid."""
    return rx.fragment(rx.cond(view.sql_open, table_sql(view, send)), _error(view), grid)


def table_widget(
    view: rx.Var[ViewData], send: Any, grid: rx.Component, actions: tuple[rx.Component, ...]
) -> rx.Component:
    """A table: row filter and SQL toggle, the SQL box (folded by default), then the grid.
    The two halves are also a SmashDb console's result (db_console_widget).
    """
    return rx.fragment(_table_bar(view, send, actions), _table_body(view, send, grid))


def _db_table(table: rx.Var[DbTable], send: Any) -> rx.Component:
    """One table of the schema tree: click to unfold its columns; ▶ shows the whole table."""
    return rx.el.div(
        rx.el.div(
            rx.el.button(
                rx.el.span(rx.cond(table.open, "▾", "▸"), class_name="db-arrow"),
                rx.el.span(table.name, class_name="db-name"),
                rx.el.span(table.rows, class_name="dim"),
                title="Show or hide its columns",
                on_click=send("db_toggle", table.name),
                class_name="db-table-row",
            ),
            rx.el.button(
                "▶",
                title="Select everything from this table",
                on_click=send("db_open", table.name),
                class_name="db-open",
            ),
            class_name="db-table-head",
        ),
        rx.cond(
            table.open,
            rx.el.div(
                rx.foreach(
                    table.columns,
                    lambda column: rx.el.div(
                        rx.el.span(column["name"], class_name="db-name"),
                        rx.el.span(column["dtype"], class_name="db-dtype"),
                        class_name="db-column",
                    ),
                ),
            ),
        ),
        class_name="db-table mono",
    )


def _db_save_row(view: rx.Var[ViewData], send: Any) -> rx.Component:
    """Assign (was "Save as"): a name for the query's result (the next free q<n>
    filled in and selected, so Enter alone saves), bound in Python like
    `q1 = <result>`; Esc folds it.
    """
    return rx.el.form(
        rx.el.span("Assign result to", class_name="dim sans"),
        rx.el.input(
            key=view.db_save_key,
            name="var_name",  # not "name": password managers read that as an identity field
            default_value=view.db_save_name,
            auto_focus=True,
            auto_complete="off",
            spell_check=False,
            on_focus=rx.call_script("document.activeElement.select()"),
            on_key_down=lambda key: rx.cond(key == "Escape", send("db_save_toggle"), rx.noop()),
            class_name="viewer-filter mono db-save-name",
        ),
        rx.el.button("Assign", type="submit", class_name="act"),
        rx.cond(view.db_save_error != "", rx.el.span(view.db_save_error, class_name="db-save-error sans")),
        rx.cond(view.db_save_note != "", rx.el.span(view.db_save_note, class_name="dim sans")),
        # the whole form (its "var_name"): a form var has no typed items to pick from here
        on_submit=lambda form: send("db_save", form),
        reset_on_submit=False,
        class_name="sql-row db-save-row",
    )


def db_console_widget(
    view: rx.Var[ViewData], send: Any, grid: rx.Component, actions: tuple[rx.Component, ...]
) -> rx.Component:
    """A SmashDb console (db_console.py), as in DataGrip: the schema tree on the left; on the
    right the query editor (Shortcut.RUN_SQL or Run; a selection runs alone), then the result,
    which is the table widget itself (its bar on top, its SQL box and grid below). A failed
    query shows its traceback with traceback_view, as a Python cell does, over the last result.
    """
    return rx.fragment(
        _table_bar(
            view,
            send,
            actions,
            inline_ai_button(".db-editor .cm-content", "Ask AI to write or change the query"),
            rx.el.button(
                rx.cond(view.db_history_open, "History ▾", "History ▸"),
                title="The queries run in this console",
                on_click=send("db_history"),
                disabled=view.db_history.length() == 0,
                class_name="act",
            ),
            rx.el.button(
                rx.cond(view.db_save_open, "Assign ▾", "Assign ▸"),
                title="Keep the query's result as a Python variable (a DataFrame, with its own tab)",
                on_click=send("db_save_toggle"),
                disabled=~view.db_ran,
                class_name="act",
            ),
        ),
        rx.el.div(
            rx.el.div(
                rx.el.div("Tables", class_name="db-tree-head sans"),
                rx.foreach(view.db_tables, lambda table: _db_table(table, send)),
                class_name="db-tree",
            ),
            rx.el.div(
                # the query, with what belongs to it: Run, Assign, History, an error
                rx.el.div(
                    rx.el.div(
                        rx.el.div(
                            sql_editor(
                                key=view.db_key,
                                initial_sql=view.db_sql,
                                schema=view.db_schema,
                                placeholder="select * from framedata",
                                keys=sql_keys(),
                                edit_url=INLINE_EDIT_URL,
                                # the base state's var: no app State import
                                # here (state.py imports this file)
                                token=rx.State.router.session.client_token,
                                on_run=lambda query: send("db_run", query),
                                on_save=lambda text: send("db_draft", text),
                            ),
                            class_name="sql-editor db-editor",
                        ),
                        rx.el.div(
                            rx.el.button(
                                rx.cond(view.running, "Running…", "Run"),
                                title=Shortcut.RUN_SQL.hint("Run the query (a selection runs alone)"),
                                on_click=send("db_run", ""),
                                disabled=view.running,
                                class_name="act",
                            ),
                            rx.el.span(Shortcut.RUN_SQL.keys, class_name="sql-hint dim mono"),
                            class_name="db-run",
                        ),
                        class_name="db-editor-row",
                    ),
                    rx.cond(view.db_save_open, _db_save_row(view, send)),
                    rx.cond(
                        view.db_history_open,
                        rx.el.div(
                            rx.foreach(
                                view.db_history,
                                lambda query: rx.el.button(
                                    query,
                                    title=query,
                                    on_click=send("db_pick", query),
                                    class_name="db-history-row mono",
                                ),
                            ),
                            class_name="db-history",
                        ),
                    ),
                    rx.cond(
                        view.trace_text != "",
                        traceback_view(view.trace, view.trace_hidden, view.trace_more, view.trace_text, "db-trace"),
                    ),
                    class_name="db-query",
                ),
                # right of the query (under it when the view is narrow): the result
                rx.el.div(
                    rx.cond(
                        view.db_ran,
                        _table_body(view, send, grid),
                        rx.el.div(
                            "Write a query and run it, or press ▶ on a table. ",
                            "Results can be filtered, sorted and queried again (SQL ▸) like any table.",
                            class_name="empty sans",
                        ),
                    ),
                    class_name="db-result",
                ),
                class_name="db-main",
            ),
            class_name="db-console",
        ),
    )


def table_sql(view: rx.Var[ViewData], send: Any) -> rx.Component:
    """The mini SQL runner (as in DBeaver): a polars SQL query on the table, named self, run
    with Shortcut.RUN_SQL; the grid then shows its
    result, still filtered and sorted by the bar.
    """
    return rx.el.div(
        rx.el.div(
            sql_editor(
                key=view.sql_key,
                initial_sql=view.sql,
                columns=view.sql_columns,
                keys=sql_keys(),
                on_run=lambda query: send("sql", query),
            ),
            class_name="sql-editor",
        ),
        rx.el.span(Shortcut.RUN_SQL.keys, class_name="sql-hint dim mono"),
        rx.cond(
            view.sql_active,
            rx.el.button("×", title="Back to the whole table", on_click=send("sql_reset"), class_name="act"),
        ),
        class_name="sql-row",
    )


def form_toggle(view: rx.Var[ViewData], send: Any) -> rx.Component:
    """The bar's button that folds the tool form open
    (tool_forms.py); highlighted while it runs.
    """
    return rx.el.button(
        rx.cond(view.form_open, "Inputs ▾", "Inputs ▸"),
        title="The inputs of the tool that made this: change them and run it again",
        on_click=send("form_toggle"),
        class_name=rx.cond(view.running | view.form_changed, "act form-toggle is-active", "act form-toggle"),
    )


def ai_toggle(view: rx.Var[ViewData], send: Any) -> rx.Component:
    """The bar's button for the form's inline chat (inline_fill.py): opens its box in the bar
    (strip_ask_box), or closes it and drops a proposal. Shortcut.INLINE_EDIT clicks it for the
    view you are in (assets/panes.js, by data-ai-toggle).
    """
    return rx.el.button(
        ai_icon(),
        title=Shortcut.INLINE_EDIT.hint("Ask AI to fill these inputs (you run them)"),
        aria_label="Ask AI to fill the inputs",
        on_click=send("ai_toggle"),
        custom_attrs={"data-ai-toggle": ""},
        class_name=rx.cond(view.ai_open, "act ai-toggle mono is-active", "act ai-toggle mono"),
    )


def inline_ai_button(target: str, what: str, flat: bool = False) -> rx.Component:
    """The robot of anything with an inline chat (Shortcut.INLINE_EDIT) that has no AI button
    of its own (a result with inputs has ai_toggle): a pane's head (flat, as its other icon
    buttons) or a view's bar. A click opens the inline chat there, as the key does
    (assets/panes.js, by data-inline-ai). target: the CSS selector, inside that pane or view,
    of where the chat opens: its code editor(s), or the Terminal's frame.
    """
    return rx.el.button(
        ai_icon(),
        title=Shortcut.INLINE_EDIT.hint(what),
        aria_label=what,
        type="button",
        custom_attrs={"data-inline-ai": target},
        class_name="zoom-btn ai-btn mono" if flat else "act ai-toggle mono",
    )


def form_section(view: rx.Var[ViewData], send: Any) -> rx.Component:
    """The tool form, folded under the bar: one compact row of the tool's inputs; Enter or Run
    runs it. Its inline chat's box is in the bar (strip_ask_box) but belongs to this form:
    Enter there asks the AI for new inputs (State.view_event gets the box's text as ASK_FIELD,
    with the inputs as they are on screen).
    """
    return tool_form(
        fields=view.form,
        running=view.running,
        changed=view.form_changed,
        on_run=lambda form: send("form_run", form),
        on_reset=send("form_reset"),
        remount=view.form_key,
        ai_busy=view.ai_busy,
        form_id=form_id(view),
    )


def _choice_input(item: rx.Var[FormField]) -> rx.Component:
    """The one pick-from-a-list input (tool_forms.picker_for), single or multiple
    (item.multiple, the only difference: whether a pick replaces the last one). A box showing
    each pick as a chip (icon when the options have one, name, x to remove) that opens the
    list; a search box on top of the list when it is long (item.search). assets/choice.js does
    the picking and draws the chips; this is its markup. The hidden input carries the picked
    values joined by "," under the field's name; "" = any.
    """

    def option(choice: rx.Var[dict[str, str]]) -> rx.Component:
        return rx.el.button(
            rx.cond(
                choice["icon"] != "",
                rx.el.img(src=ICON_URL + choice["icon"], alt="", loading="lazy", class_name="char-icon"),
            ),
            rx.el.span(choice["label"], class_name="choice-label"),
            rx.el.span("✓", class_name="choice-check"),
            type="button",
            tab_index=-1,
            custom_attrs={
                "data-value": choice["value"],
                "data-label": choice["label"],
                "data-icon": rx.cond(choice["icon"] != "", ICON_URL + choice["icon"], ""),
            },
            class_name="choice-option",
        )

    return rx.el.span(
        rx.el.span(
            # filled by choice.js from the hidden value (it owns this span's contents)
            rx.el.span(class_name="choice-chips", custom_attrs={"data-choice-chips": ""}),
            rx.el.span("▾", class_name="choice-caret dim"),
            tab_index=0,
            class_name="form-input choice-box",
            custom_attrs={"data-choice-box": "", "role": "combobox"},
        ),
        rx.el.input(type="hidden", name=item.name, default_value=item.value, custom_attrs={"data-choice-value": ""}),
        rx.el.span(
            rx.cond(
                item.search,
                rx.el.input(
                    placeholder="Search…",
                    auto_complete="off",
                    spell_check=False,
                    class_name="form-input choice-search",
                    custom_attrs={"data-choice-search": ""},
                ),
            ),
            rx.el.span(
                rx.foreach(item.choices, option), class_name="choice-options", custom_attrs={"data-choice-options": ""}
            ),
            class_name="choice-list",
            custom_attrs={"data-choice-list": ""},
        ),
        class_name="choice",
        custom_attrs={"data-choice": "", "data-multiple": rx.cond(item.multiple, "true", "false")},
    )


def _form_field(item: rx.Var[FormField]) -> rx.Component:
    control = rx.match(
        item.kind,
        ("choice", _choice_input(item)),
        (
            "select",
            rx.el.select(
                rx.foreach(
                    item.options, lambda option: rx.el.option(rx.cond(option == "", "any", option), value=option)
                ),
                name=item.name,
                default_value=item.value,
                class_name="form-input",
            ),
        ),
        ("check", rx.el.input(type="checkbox", name=item.name, default_checked=item.value != "")),
        rx.el.input(
            name=item.name,
            default_value=item.value,
            type=rx.cond(item.kind == "number", "number", "text"),
            class_name="form-input",
        ),
    )
    return rx.el.label(
        rx.el.span(item.label, class_name="form-label"),
        control,
        title=item.help,
        # changed: the AI's proposal differs here (inline_fill.py);
        # the tooltip says what it was
        class_name=rx.cond(item.changed, "form-field is-changed", "form-field"),
    )


def form_id(view: rx.Var[ViewData]) -> rx.Var[str]:
    """The id of a view's tool form: its bar's Ask AI box belongs to that form (the HTML form=
    attribute), though it is drawn outside it, in the bar.
    """
    return "form-" + view.slot.to(str)


def strip_ask_box(view: rx.Var[ViewData]) -> rx.Component:
    """A form's inline chat, in the widget's bar (the free width left of its buttons): the box
    to tell the AI what the inputs should be, and at its right what the last call used, why it
    failed, or "Thinking…". The same markup as every inline AI box (ui/inline_box.js;
    assets/app.css). It belongs to the form, so Enter here submits the form with the inputs as
    they are on screen. It remounts with the form (form_key), so it takes the focus when it
    appears and after each proposal, and Enter again, with the box empty, runs the proposal.
    Esc, Alt+I or the lit ✨ close it (and drop a proposal).
    """
    status = rx.cond(
        view.ai_busy,
        rx.el.span("Thinking…", class_name="inline-box-status"),
        rx.cond(
            view.ai_error != "",
            rx.el.span(view.ai_error, title=view.ai_error, class_name="inline-box-status is-error"),
            rx.el.span(
                rx.cond(view.ai_note != "", view.ai_note, "Enter asks AI · Esc closes"),
                title=view.ai_note,
                class_name="inline-box-status",
            ),
        ),
    )
    return rx.el.div(
        rx.el.div(
            rx.el.span(ai_icon(), class_name="inline-box-icon"),
            rx.el.input(
                name=ASK_FIELD,
                placeholder=rx.cond(
                    view.ai_proposed,
                    "Enter runs these inputs · or say what else to change · Esc puts the old ones back",
                    "Say what the inputs should be, eg: sparg0 vs steve, offline, last 90 sets",
                ),
                auto_focus=True,
                auto_complete="off",
                spell_check=False,
                read_only=view.ai_busy,
                key=view.form_key,
                class_name="inline-box-input",
                custom_attrs={"form": form_id(view)},
            ),
            status,
            class_name=rx.cond(view.ai_busy, "inline-box is-thinking", "inline-box"),
        ),
        class_name="strip-ask",
        custom_attrs={"data-ask-box": ""},
    )


@rx.memo
def tool_form(
    fields: rx.Var[list[FormField]],
    running: rx.Var[bool],
    changed: rx.Var[bool],
    remount: rx.Var[str],
    on_run: rx.EventHandler[passthrough_event_spec(dict[str, Any])],
    on_reset: rx.EventHandler[no_args_event_spec],
    ai_busy: rx.Var[bool],
    form_id: rx.Var[str],
) -> rx.Component:
    """The form itself. A memo component, as compact_grid is: a form's submit handler is
    generated outside any loop the view sits in (chat items, cells)
    and couldn't see the loop item otherwise.
    """
    return rx.el.form(
        rx.foreach(fields, _form_field),
        rx.el.button(
            rx.cond(running, "Running…", "Run"),
            type="submit",
            disabled=running | ai_busy,
            title="Run the tool with these inputs (Enter; with text in the Ask AI box, Enter asks the AI instead)",
            class_name="act",
        ),
        rx.cond(
            changed,
            rx.el.button(
                "×",
                type="button",
                title="Back to the agent's original call (its inputs and result)",
                on_click=on_reset,
                class_name="act",
            ),
        ),
        # a new key remounts the inputs, so they show a new result's values
        key=remount,
        on_submit=on_run,
        # the bar's Ask AI box submits with it (strip_ask_box, form=)
        id=form_id,
        class_name="tool-form sans",
    )


def trace_part(part: rx.Var) -> rx.Component:
    """One piece of a traceback (session.trace_parts):
    the full standard traceback, styled by role.
    """
    return rx.match(
        part["kind"],
        (
            "frame",
            rx.el.div(
                rx.el.div(
                    rx.el.span(part["path"], class_name="tb-path"),
                    rx.el.span(", line ", class_name="dim"),
                    rx.el.span(part["line"], class_name="tb-line"),
                    rx.cond(
                        part["func"] != "",
                        rx.el.span(
                            rx.el.span(", in ", class_name="dim"), rx.el.span(part["func"], class_name="tb-func")
                        ),
                    ),
                ),
                rx.cond(
                    (part["pre"] != "") | (part["mark"] != ""),
                    rx.el.div(
                        part["pre"],
                        rx.el.span(part["mark"], class_name="tb-mark"),
                        part["post"],
                        class_name="tb-code",
                    ),
                ),
                class_name="tb-frame is-" + part["where"].to(str),
            ),
        ),
        (
            "error",
            rx.el.div(
                rx.el.span(part["module"], class_name="tb-module"),
                rx.el.span(part["name"], class_name="tb-name"),
                rx.cond(part["text"] != "", rx.el.span(": ", part["text"], class_name="tb-msg")),
                class_name="tb-error",
            ),
        ),
        ("chain", rx.el.div(part["text"], class_name="tb-chain")),
        rx.el.div(part["text"], class_name="tb-dim"),
    )


def copy_button(text: rx.Var[str] | str, what: str = "", label: str = "") -> rx.Component:
    """The small copy button of a code block: copies text; assets/panes.js does it (data-copy)
    and shows a tick for a moment. label: a word instead of the copy icon, eg "curl".
    """
    return rx.el.button(
        rx.el.span(f"{ICON_COPY} {label}" if label else ICON_COPY, class_name="when-idle"),
        rx.el.span(f"{ICON_COPIED} {label}" if label else ICON_COPIED, class_name="when-copied"),
        title=f"Copy {what}".strip(),
        aria_label=f"Copy {what}".strip(),
        type="button",
        custom_attrs={"data-copy": text},
        class_name="copy-btn mono",
    )


def traceback_view(trace: rx.Var, hidden: rx.Var, more: rx.Var, text: rx.Var, class_name: str = "") -> rx.Component:
    """An error's traceback, the same under a Python cell, in the chat and in a SmashDb
    console: the frame that raised and the error always shown, everything above it folded in a
    <details>, and a copy button for the full plain-text traceback
    (text). Without styled parts it shows the plain text.
    """
    return rx.el.div(
        copy_button(text, "the full traceback"),
        rx.cond(
            trace.length() > 0,
            rx.fragment(
                rx.cond(
                    hidden.length() > 0,
                    rx.el.details(
                        rx.el.summary(more, class_name="tb-toggle sans"),
                        rx.foreach(hidden, trace_part),
                    ),
                ),
                rx.foreach(trace, trace_part),
            ),
            rx.el.pre(text, class_name="tb-plain"),
        ),
        class_name=f"cell-trace mono {class_name}".strip(),
    )


def link(text: Any, href: Any, class_name: str = "") -> rx.Component:
    """A hyperlink in a widget. THE way to show one: every link in every widget goes through
    here, so it looks like a link in the agent's markdown (blue, underlined: `a.link` in
    app.css) and opens in a new tab. class_name adds layout only (eg truncation), never colour.
    (A link drawn as a button, eg the video player's "YouTube ↗", is a button: class `act`.)
    """
    return rx.el.a(
        text, href=href, target="_blank", rel="noreferrer", class_name=f"link {class_name}".strip(), title=href
    )


def _bar_row(row: rx.Var[BarRow]) -> rx.Component:
    return rx.el.div(
        rx.cond(
            row.icon != "", rx.el.img(src=row.icon, alt="", class_name="char-icon"), rx.el.span(class_name="char-icon")
        ),
        rx.el.span(row.label, class_name="bar-label"),
        rx.el.span(rx.el.span(style={"width": row.width}, class_name="bar-fill"), class_name="bar-track"),
        rx.el.span(row.value, class_name="bar-value"),
        title=row.tip,
        class_name="bar-row",
    )


def bar_group(group: rx.Var[BarGroup], *head: rx.Component) -> rx.Component:
    """A ranked-bar list: title, what the shares are of, then one row per part, largest first.
    One hue: the rows are compared by length, and told apart by their label (and icon).
    """
    return rx.el.div(
        rx.el.div(
            rx.el.span(group.title, class_name="usage-title"),
            *head,
            rx.el.span(group.note, class_name="dim"),
            class_name="usage-head",
        ),
        rx.cond(
            group.rows.length() > 0,
            rx.el.div(
                rx.foreach(group.rows, _bar_row), class_name=rx.cond(group.icons, "bar-rows", "bar-rows no-icons")
            ),
            rx.el.div("no data", class_name="dim"),
        ),
        class_name="usage-group",
    )


def usage_widget(view: rx.Var[ViewData], send: Any, actions: tuple[rx.Component, ...]) -> rx.Component:
    """A player's usage at a glance (start.gg sets): characters for a picked window, stages by
    who picked them, a line on character changes, and
    the characters at each of the last events.
    """
    windows = rx.el.span(
        rx.foreach(
            view.windows,
            lambda window: rx.el.button(
                window["label"],
                title=window["tip"],
                on_click=send("window", window["key"]),
                class_name=rx.cond(window["on"] != "", "seg is-on", "seg"),
            ),
        ),
        class_name="segs",
    )

    settings = rx.el.span(
        rx.foreach(
            view.settings,
            lambda setting: rx.el.button(
                setting["label"],
                title=setting["tip"],
                disabled=view.running,
                on_click=send("setting", setting["key"]),
                class_name=rx.cond(setting["on"] != "", "seg is-on", "seg"),
            ),
        ),
        class_name="segs",
    )

    def event_row(event: rx.Var[EventRow]) -> rx.Component:
        return rx.el.div(
            rx.el.span(event.date, class_name="event-date mono"),
            # where it was played: a filled tag for in-person, an outlined one for online
            rx.el.span(
                event.where,
                class_name=rx.match(
                    event.where,
                    ("online", "event-where is-online"),
                    ("offline", "event-where is-offline"),
                    "event-where",
                ),
            ),
            rx.el.span(
                rx.foreach(
                    event.icons,
                    lambda icon: rx.cond(
                        icon["url"] != "",
                        rx.el.img(src=icon["url"], alt=icon["name"], title=icon["name"], class_name="char-icon"),
                        rx.el.span(icon["name"], class_name="dim"),
                    ),
                ),
                class_name="event-icons",
            ),
            rx.cond(
                event.url != "",
                link(event.title, event.url, class_name="event-title"),
                rx.el.span(event.title, class_name="event-title"),
            ),
            title=event.tip,
            class_name="event-row",
        )

    return rx.fragment(
        _bar(view, actions, send=send),
        rx.cond(view.form_open, form_section(view, send)),
        _error(view),
        rx.el.div(
            rx.el.div(
                rx.el.span("Events counted", class_name="dim"),
                settings,
                rx.cond(view.running, rx.el.span("loading…", class_name="dim")),
                class_name="usage-settings",
            ),
            bar_group(view.chars, windows),
            # next to the characters, on the top row: the newest events at a glance
            rx.el.div(
                rx.el.div(
                    rx.el.span("Last events", class_name="usage-title"),
                    rx.el.span(view.events_note, class_name="dim"),
                    class_name="usage-head",
                ),
                rx.cond(
                    view.events.length() > 0,
                    rx.el.div(rx.foreach(view.events, event_row), class_name="event-rows"),
                    rx.el.div("no data", class_name="dim"),
                ),
                class_name="usage-group is-events",
            ),
            rx.cond(view.switch_note != "", rx.el.div(view.switch_note, class_name="usage-switches dim")),
            rx.foreach(view.stage_groups, lambda group: bar_group(group)),
            class_name="usage sans",
        ),
    )


def web_frame(
    title: rx.Component,
    src: Any,
    url: Any,
    key: Any = "",
    extra: tuple[rx.Component, ...] = (),
    after: tuple[rx.Component, ...] = (),
    blocked: Any = False,
    body: rx.Component | None = None,
    class_name: Any = "player",
) -> rx.Component:
    """A web page in a frame, under a bar: title (or an address box), the caller's extra
    buttons, Open ↗ (a real browser tab), then `after` (eg close, float). The Browser widget
    is this alone; the VODs player is this with its list button. One look for both.
    """
    frame = rx.el.iframe(
        src=src,
        allow="autoplay; encrypted-media; picture-in-picture; fullscreen; clipboard-write",
        # YouTube refuses to play (error 153) when the embedding page sends no referrer
        referrer_policy="strict-origin-when-cross-origin",
        key=key,
        class_name="player-frame",
    )
    return rx.el.div(
        rx.el.div(
            title,
            *extra,
            rx.el.a("Open ↗", href=url, target="_blank", rel="noreferrer", title=url, class_name="act"),
            *after,
            class_name="player-bar sans",
        ),
        # while `blocked`, `body` (eg the Browser's refused card) takes the frame's place
        rx.cond(blocked, body if body is not None else rx.fragment(), frame),
        class_name=class_name,
    )


def browser_widget(view: rx.Var[ViewData], send: Any, actions: tuple[rx.Component, ...]) -> rx.Component:
    """The Browser: an address box (Enter loads it) over the page (web_frame). A site the
    check found refusing (web.frameable) gets an 'Open in new tab' card instead of a blank
    frame; when the check had no answer the page is framed with a hint, as a refused frame
    looks blank and the page itself can't tell.
    """
    web = view.web
    address = rx.el.form(
        rx.el.input(
            key=web["url"],
            name="url",
            default_value=web["url"],
            placeholder="Type a web address, Enter to load",
            auto_complete="off",
            spell_check=False,
            class_name="viewer-filter mono browser-url",
        ),
        on_submit=lambda form: send("navigate", form),
        reset_on_submit=False,
        class_name="browser-address",
    )
    refused = rx.el.div(
        rx.el.div(web["host"], " can't be shown here", class_name="browser-refused-title"),
        rx.el.div(
            "The site doesn't allow other pages to show it (",
            web["why"],
            "), against clickjacking.",
            class_name="dim",
        ),
        rx.el.a("Open in new tab ↗", href=web["url"], target="_blank", rel="noreferrer", class_name="act browser-open"),
        class_name="browser-refused sans",
    )
    # Back / Forward are the browser's own keys (Chromium's Alt+Left / Alt+Right): they step
    # through the pages followed by clicking inside the page, as in any browser tab
    keys = rx.el.span(
        "Alt+← Back · Alt+→ Forward",
        title="Go back or forward through pages you opened by clicking links inside this page",
        class_name="browser-keys dim mono",
    )
    frame = web_frame(
        address,
        src=web["src"],
        url=web["url"],
        key=web["src"],
        extra=(keys,),
        after=(*actions, float_button(), close_view_button(send)),
        blocked=web["frameable"] == "no",
        body=refused,
        class_name="player is-full browser",
    )
    return rx.fragment(
        frame,
        rx.cond(
            (web["url"] != "") & (web["frameable"] == "unknown"),
            rx.el.div(
                "Blank? This site may not allow being shown here: use Open ↗.", class_name="browser-hint dim sans"
            ),
        ),
    )


def video_widget(view: rx.Var[ViewData], send: Any, actions: tuple[rx.Component, ...]) -> rx.Component:
    """VODs (match videos): the list, and the video picked from it playing above the list.

    Picking a video folds the list away (view.list_hidden) so the video fills the component;
    the player's bar brings the list back.
    """
    playing = view.playing
    hidden = view.list_hidden
    # the Browser widget's frame (web_frame), with the list's own button and close
    player = rx.cond(
        playing["id"],
        web_frame(
            rx.el.span(playing["title"], class_name="player-title"),
            src=rx.cond(view.autoplay, f"{playing['embed']}?autoplay=1", playing["embed"]),
            url=playing["url"],
            key=playing["id"],
            extra=(
                rx.el.button(
                    rx.cond(hidden, "Show list ▾", "Hide list ▴"),
                    title="Show or hide the video list under the player",
                    on_click=send("toggle_list"),
                    class_name="act",
                ),
            ),
            # the list's bar (with its float button) is hidden while the video fills the view
            after=(
                rx.el.button("×", title="Close the player", on_click=send("stop"), class_name="act"),
                rx.cond(hidden, rx.fragment(float_button(), close_view_button(send))),
            ),
            class_name=rx.cond(hidden, "player is-full", "player"),
        ),
    )
    return rx.fragment(
        _bar(
            view,
            actions,
            rx.cond(view.paging, rx.el.span("loading…", class_name="dim")),
            rx.el.button(
                "‹ Prev",
                on_click=send("page", -1),
                disabled=view.paging | (view.page <= 1),
                class_name="act",
            ),
            rx.el.button(
                "Next ›",
                on_click=send("page", 1),
                disabled=view.paging | (view.page >= view.pages),
                class_name="act",
            ),
            hidden=hidden,
            send=send,
        ),
        rx.cond(view.form_open & ~hidden, form_section(view, send)),
        _error(view),
        player,
        rx.el.div(
            video_gallery(view.videos, lambda video: send("play", video), playing["id"]),
            class_name=rx.cond(hidden, "video-list is-hidden", "video-list"),
        ),
    )


GRID_THEME = {
    "accent_color": BLUE,
    "accent_fg": BG0,
    "accent_light": "rgba(127, 187, 179, 0.16)",
    "bg_cell": BG0,
    "bg_cell_medium": BG1,
    "bg_header": BG1,
    "bg_header_has_focus": BG2,
    "bg_header_hovered": BG2,
    "border_color": BG2,
    "horizontal_border_color": BG2,
    "header_bottom_border_color": BG4,
    "text_dark": FG,
    "text_medium": GREY2,
    "text_light": GREY1,
    "text_header": FG,
    "text_header_selected": BG0,
    "font_family": "JetBrainsMono Nerd Font, JetBrains Mono, monospace",
    "base_font_style": "13px",
    "header_font_style": "600 13px",
}

# Polars-notebook-style headers: column name, then its dtype in italics on the line below.
# The grid only draws one-line headers, so a canvas callback draws both. The grid copies only
# its own known column fields, so the dtype is looked up in the columns value by index;
# columns without one (eg the row-number column, index -1) fall back to the default drawing.
_DRAW_HEADER_JS = """((args, drawContent) => {
  const column = (COLUMNS)[args.columnIndex];
  if (!column || !column.dtype) return drawContent();
  const { ctx, theme, rect } = args;
  const x = rect.x + theme.cellHorizontalPadding;
  ctx.textBaseline = "middle";
  ctx.textAlign = "left";
  ctx.fillStyle = theme.textHeader;
  ctx.font = theme.headerFontFull;
  ctx.fillText(column.title, x, rect.y + rect.height * 0.34);
  ctx.fillStyle = theme.textLight;
  ctx.font = "italic " + theme.baseFontFull;
  ctx.fillText(column.dtype, x, rect.y + rect.height * 0.72);
})"""


def draw_header(columns: rx.Var) -> rx.Var:
    """The grid's drawHeader callback for these columns
    (keeps the columns Var's state dependency).
    """
    return rx.Var(_DRAW_HEADER_JS.replace("COLUMNS", str(columns)), _var_data=columns._get_all_var_data())  # noqa: SLF001  # Reflex has no public way to carry it over


# Cell result grids: same look, smaller type and padding so a result stays compact.
CELL_GRID_THEME = {
    **GRID_THEME,
    "base_font_style": "12px",
    "header_font_style": "600 12px",
    "cell_horizontal_padding": 8,
    "cell_vertical_padding": 2,
}


def _header_click(pos: rx.Var[int]) -> tuple[rx.Var[int]]:
    """Glide reports a header click as the bare column index."""
    return (pos,)


def full_grid(view: rx.Var[ViewData], on_sort: Any) -> rx.Component:
    """A table filling its pane (tabs)."""
    return rx.el.div(
        rx.data_editor(
            columns=view.columns,
            data=view.rows,
            rows=view.rows.length(),
            theme=GRID_THEME,
            row_markers="number",
            row_height=28,
            header_height=44,
            smooth_scroll_x=True,
            smooth_scroll_y=True,
            column_select="none",
            on_header_clicked=on_sort,
            custom_attrs={"drawHeader": draw_header(view.columns)},
            height="100%",
        ),
        class_name="viewer-grid",
    )


@rx.memo
def compact_grid(
    columns: rx.Var[list[dict[str, Any]]],
    rows: rx.Var[list[list[Any]]],
    height: rx.Var[str],
    on_sort: rx.EventHandler[_header_click],
) -> rx.Component:
    """A table sized to its content (cell outputs).

    A memo component gives each cell's grid its own scope; the grid's data callback is
    generated outside the cells loop and couldn't see a loop item otherwise.
    """
    return rx.el.div(
        rx.data_editor(
            columns=columns,
            data=rows,
            rows=rows.length(),
            theme=CELL_GRID_THEME,
            row_markers="number",
            row_height=OUTPUT_ROW_HEIGHT,
            header_height=OUTPUT_HEADER_HEIGHT,
            smooth_scroll_x=True,
            smooth_scroll_y=True,
            column_select="none",
            on_header_clicked=on_sort,
            custom_attrs={"drawHeader": draw_header(columns)},
            height="100%",
        ),
        style={"height": height},
        class_name="cell-grid",
    )


def video_gallery(videos: rx.Var, on_play: Any, playing_id: rx.Var[str] | str = "") -> rx.Component:
    """VODs (match videos) as thumbnail cards: title, date
    and players. A click calls on_play(video).
    """

    def card(video: rx.Var) -> rx.Component:
        return rx.el.button(
            rx.el.span(
                rx.el.img(src=video["thumb"], alt="", loading="lazy"),
                rx.el.span("▶", class_name="play"),
                class_name="thumb",
            ),
            rx.el.span(video["title"], class_name="video-title"),
            rx.el.span(
                video["date"], rx.cond(video["players"] != "", " · ", ""), video["players"], class_name="video-meta"
            ),
            title=video["title"],
            on_click=on_play(video),
            class_name=rx.cond(video["id"] == playing_id, "video-card is-playing", "video-card"),
        )

    return rx.cond(
        videos.length() > 0,
        rx.el.div(rx.foreach(videos, card), class_name="video-gallery sans"),
        rx.el.div("No VODs matched this search.", class_name="empty sans"),
    )


def model_fields(fields: rx.Var, sections: rx.Var) -> rx.Component:
    """Generic view of a pydantic model: its fields as name/value
    rows, each list of models as a table.
    """
    return rx.el.div(
        rx.el.div(
            rx.foreach(
                fields,
                lambda field: rx.fragment(
                    rx.el.span(field["name"], class_name="field-name"),
                    rx.el.span(field["value"], class_name="field-value"),
                ),
            ),
            class_name="field-list",
        ),
        rx.foreach(
            sections,
            lambda section: rx.el.div(
                rx.el.div(section.title, class_name="section-title"),
                rx.el.div(
                    rx.el.table(
                        rx.el.thead(rx.el.tr(rx.foreach(section.columns, lambda column: rx.el.th(column)))),
                        rx.el.tbody(
                            rx.foreach(
                                section.rows, lambda row: rx.el.tr(rx.foreach(row, lambda value: rx.el.td(value)))
                            )
                        ),
                    ),
                    class_name="section-table",
                ),
            ),
        ),
        class_name="model-view mono",
    )
